 "content": "def transform(grid):
    """Fill each vertical column marked by a 5 in the bottom row.

    Empty cells inherit the nearest nonzero cell below them in that column.
    """
    out = [row[:] for row in grid]
    if not out:
        return out
    last = len(out) - 1
    for col, value in enumerate(out[last]):
        if value != 5:
            continue
        carry = 0
        for row in range(last, -1, -1):
            if out[row][col] != 0:
                carry = out[row][col]
            elif carry:
                out[row][col] = carry
    return out


